#include <iostream>
#include <string>

unsigned long long checksum(const std::string& text) {
    unsigned long long sum = 0;
    for (unsigned char byte : text) sum += byte;
    return sum;
}
int main() {
    std::string text;
    std::getline(std::cin, text);
    std::cout << checksum(text) << '\n' << text << '\n';
}
